            res = res.replace(/^([\d,]+)\s*\/\s*([\d,]+)\s*tokens\s*\(([\d.]+%?)\)$/gi, '$1 / $2 Tokens ($3)');
            res = res.replace(/^\(([\d,]+)\s*tokens\)(.*)$/gi, '($1 Tokens)$2');
