            res = res.replace(/Modified in\s+([\s\S]+)/gi, '已在 $1 中修改');
            res = res.replace(/Learn more about\s+([\s\S]+)/gi, '了解更多关于 $1');
            res = res.replace(/Learn more\s+关于\s+([\s\S]+)/gi, '了解更多关于 $1');
